$rows=$pdo->query("SELECT * FROM periode_voting ORDER BY id DESC")->fetchAll();$pageTitle='Periode Voting';require __DIR__.'/../includes/header.php';?>
<section class="page-intro"><h1>Periode Voting</h1><p>Aktifkan periode dan tentukan waktu mulai serta berakhirnya pemilihan.</p></section><div class="admin-nav"><a href="dashboard.php">Dashboard</a><a href="kontestan.php">Kontestan</a><a href="pemilih.php">Pemilih</a><a class="active" href="periode.php">Periode</a><a href="hasil-voting.php">Hasil voting</a></div><div class="admin-panel"><h2>Buat periode baru</h2><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form class="admin-form" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Nama periode</label><input name="nama_periode" required><label>Tanggal mulai</label><input type="datetime-local" name="tanggal_mulai" required><label>Tanggal selesai</label><input type="datetime-local" name="tanggal_selesai" required><button class="btn btn-gold">Buat dan aktifkan periode</button></form></div><div class="admin-panel"><h2>Riwayat periode</h2><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Mulai</th><th>Selesai</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['nama_periode']) ?></td><td><?= e($r['tanggal_mulai']) ?></td><td><?= e($r['tanggal_selesai']) ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
